import{_ as a,o as s,c as e,a2 as l}from"./chunks/framework.BbQrW5_t.js";const c=JSON.parse('{"title":"SRC 实战与 CISP-PTE","description":"","frontmatter":{"title":"SRC 实战与 CISP-PTE","date":"2026-09-03T00:00:00.000Z","tags":["网络安全","中级"]},"headers":[],"relativePath":"study/cyber-security/chapters/中级篇/09-SRC实战与CISP-PTE.md","filePath":"study/cyber-security/chapters/中级篇/09-SRC实战与CISP-PTE.md","lastUpdated":1788493831000}'),o={name:"study/cyber-security/chapters/中级篇/09-SRC实战与CISP-PTE.md"};function i(n,t,r,d,p,h){return s(),e("div",null,[...t[0]||(t[0]=[l(`<h1 id="_09-·-src-实战与-cisp-pte——合法战场与硬证书" tabindex="-1">09 · SRC 实战与 CISP-PTE——合法战场与硬证书 <a class="header-anchor" href="#_09-·-src-实战与-cisp-pte——合法战场与硬证书" aria-label="Permalink to &quot;09 · SRC 实战与 CISP-PTE——合法战场与硬证书&quot;">​</a></h1><blockquote><p>SRC（安全应急响应中心）是你唯一能对<strong>真实系统</strong>合法动手的地方；CISP-PTE 是国内攻防岗简历上的硬通货。这一章讲清楚&quot;怎么打才合法、怎么考才高效&quot;。</p></blockquote><h2 id="🎯-学习目标" tabindex="-1">🎯 学习目标 <a class="header-anchor" href="#🎯-学习目标" aria-label="Permalink to &quot;🎯 学习目标&quot;">​</a></h2><ol><li>说清 SRC 平台的授权边界与行为红线</li><li>建立可持续的挖洞工作流</li><li>写出&quot;一次通过&quot;的漏洞报告</li><li>完成 CISP-PTE 考纲与备考计划</li></ol><h2 id="📖-核心知识" tabindex="-1">📖 核心知识 <a class="header-anchor" href="#📖-核心知识" aria-label="Permalink to &quot;📖 核心知识&quot;">​</a></h2><h3 id="_9-1-src-生态与授权边界" tabindex="-1">9.1 SRC 生态与授权边界 <a class="header-anchor" href="#_9-1-src-生态与授权边界" aria-label="Permalink to &quot;9.1 SRC 生态与授权边界&quot;">​</a></h3><table tabindex="0"><thead><tr><th>平台</th><th>特点</th><th>新手友好度</th></tr></thead><tbody><tr><td>补天</td><td>漏洞量大、企业多</td><td>⭐⭐⭐⭐</td></tr><tr><td>漏洞盒子</td><td>同上</td><td>⭐⭐⭐⭐</td></tr><tr><td>厂商 SRC（字节/阿里/腾讯等）</td><td>范围清晰、规则严、奖励高</td><td>⭐⭐（要求高）</td></tr></tbody></table><p><strong>授权边界铁律</strong>：</p><ul><li>只测平台公告范围（SRC 的 scope 页面），范围外一行代码都不碰</li><li>遵守速率限制——把业务打挂=违法（285/286 条不豁免）</li><li>拿到数据即止：<strong>不下载、不翻页、不截图敏感内容</strong>（证明漏洞的最小证据即可）</li><li>发现高危不扩大战果：验证到&quot;能进&quot;就停，立刻报告</li></ul><h3 id="_9-2-挖洞工作流-可持续版" tabindex="-1">9.2 挖洞工作流（可持续版） <a class="header-anchor" href="#_9-2-挖洞工作流-可持续版" aria-label="Permalink to &quot;9.2 挖洞工作流（可持续版）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 资产测绘（目标主域）: 子域名枚举(你的工具) → 存活探测 → 指纹识别</span></span>
<span class="line"><span>2. 边缘资产优先: 老系统/测试环境/被遗忘的子域——补丁滞后区</span></span>
<span class="line"><span>3. 漏洞匹配: 指纹 → 历史漏洞清单(挂 UI 查) + 逻辑漏洞测试(中级篇 02 的 checklist)</span></span>
<span class="line"><span>4. 验证与取证: 最小化 PoC（一条请求+一个截图）</span></span>
<span class="line"><span>5. 提交 → 按平台模板；被拒=学习机会（看官方拒因：无法复现/范围外/低危）</span></span></code></pre></div><p>节奏建议：<strong>月更节奏</strong>——每月一个完整周末做资产测绘+批量测试，比每天摸 20 分钟高效（碎片时间用来读漏洞报告）。</p><h3 id="_9-3-报告公式-低危→高分的秘密" tabindex="-1">9.3 报告公式（低危→高分的秘密） <a class="header-anchor" href="#_9-3-报告公式-低危→高分的秘密" aria-label="Permalink to &quot;9.3 报告公式（低危→高分的秘密）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>标题：[厂商][系统][漏洞类型]一句话（例：XX 学院招生系统存在未授权访问可查询全部考生信息）</span></span>
<span class="line"><span>危害定级：说&quot;业务影响&quot;不说&quot;技术名词&quot;（可查 3 万考生身份证号 &gt; &quot;未授权接口&quot;）</span></span>
<span class="line"><span>复现步骤：1-2-3 步，每步一条请求/一个截图，可直接照抄复现</span></span>
<span class="line"><span>影响面：波及多少用户/什么数据/能进一步到哪</span></span>
<span class="line"><span>修复建议：具体到代码层（加鉴权注解/收紧 CORS/下线接口）</span></span></code></pre></div><p>被拒 Top3 原因：复现不了（步骤缺失）、范围外（测了不该测的）、重复提交——<strong>报告质量决定通过率</strong>。</p><h3 id="_9-4-cisp-pte-备考" tabindex="-1">9.4 CISP-PTE 备考 <a class="header-anchor" href="#_9-4-cisp-pte-备考" aria-label="Permalink to &quot;9.4 CISP-PTE 备考&quot;">​</a></h3><p>考纲四模块与权重：Web 渗透（注入/XSS/文件上传/命令执行）、中间件（Tomcat/Weblogic/JBoss 历史洞）、操作系统（Windows/Linux 提权）、内网（MSF 基础）。</p><table tabindex="0"><thead><tr><th>阶段</th><th>时间</th><th>动作</th></tr></thead><tbody><tr><td>对照缺口</td><td>2 周</td><td>考纲逐项自评，标记弱项</td></tr><tr><td>专项攻坚</td><td>4 周</td><td>弱模块各配 2-3 个靶场实战</td></tr><tr><td>全真模拟</td><td>2 周</td><td>限时完整流程演练（发题→报告）</td></tr><tr><td>手速与细节</td><td>1 周</td><td>截图习惯/报告模板背熟</td></tr></tbody></table><p>实战考试要点：<strong>过程截图即证据</strong>——考官按&quot;攻击链完整性+报告质量&quot;评分，不是只看 flag。</p><h2 id="🔬-动手实操" tabindex="-1">🔬 动手实操 <a class="header-anchor" href="#🔬-动手实操" aria-label="Permalink to &quot;🔬 动手实操&quot;">​</a></h2><p>注册补天 → 只看&quot;公开教育行业公益测试范围&quot;资产 → 用你的子域名工具跑第一个目标 → 全程遵守 9.1 铁律 → 第一份报告（哪怕低危）。</p><h2 id="⚠️-常见坑" tabindex="-1">⚠️ 常见坑 <a class="header-anchor" href="#⚠️-常见坑" aria-label="Permalink to &quot;⚠️ 常见坑&quot;">​</a></h2><ol><li>Scope 之外&quot;顺手&quot;测同 IP 其他站点——超范围即违法</li><li>高危洞&quot;多翻几页证明危害&quot;——翻页=侵犯公民个人信息，红线</li><li>报告只贴 payload 不写步骤——复现不了=拒单</li><li>备考只刷题不做靶机——PTE 是实操考</li><li>收集&quot;证明材料&quot;过度——最小证据原则，保护自己也保护他人</li></ol><h2 id="✅-自测题" tabindex="-1">✅ 自测题 <a class="header-anchor" href="#✅-自测题" aria-label="Permalink to &quot;✅ 自测题&quot;">​</a></h2><details><summary>1. SRC 测试为什么&quot;拿到数据即止&quot;？</summary><p>法律上&quot;获取数据&quot;的量与类型决定是否触刑（侵犯公民个人信息罪）；渗透的目的是证明漏洞存在，不是展示破坏力——最小证据原则既合规也是职业素养。</p></details><details><summary>2. 为什么&quot;边缘资产&quot;优先测？</summary><p>测试环境/老系统补丁与监控通常滞后于主站，攻击者实际也这么想——投入产出比最高，且多为低危起步的好战场。</p></details><details><summary>3. 报告标题的三个要素？</summary><p>厂商+系统+漏洞类型与一句话影响——让审核员 3 秒判断价值与归属。</p></details><details><summary>4. PTE 实操考的评分重心？</summary><p>攻击链完整性与报告质量：过程截图、每步依据、修复建议——只拿 flag 不写过程得不了高分。</p></details><details><summary>5. 被拒后正确的动作？</summary><p>读拒因→区分&quot;质量差/范围外/重复&quot;→属质量问题按公式改写重交，属范围问题立即停止该目标——把拒单当免费评审。</p></details><h2 id="🔗-对应周任务与资源" tabindex="-1">🔗 对应周任务与资源 <a class="header-anchor" href="#🔗-对应周任务与资源" aria-label="Permalink to &quot;🔗 对应周任务与资源&quot;">​</a></h2><ul><li><strong>W93-W104</strong>；资源：补天/漏洞盒子新人规则页、CISP-PTE 官方考纲、先知社区报告集</li></ul>`,31)])])}const q=a(o,[["render",i]]);export{c as __pageData,q as default};
